package net.civeira.phylax.feature.observe.observedissue.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class CulpritVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property culprit of observed issue ")
  void test_culprit_v_o_builder() {
    Assertions.assertFalse(CulpritVO.nullValue().getCulprit().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(CulpritVO.tryFrom(null).getCulprit().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", CulpritVO.from("one").getCulprit().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> CulpritVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", CulpritVO.from("one").toString());
  }
}
